set -euo pipefail
BUILD_DIR=$(mktemp -d /opt/brigada-build-XXXXXX)
base64 -d > "$BUILD_DIR/source.tgz" <<'BRIGADA_SOURCE'

BRIGADA_SOURCE
tar -xzf "$BUILD_DIR/source.tgz" -C "$BUILD_DIR"
/opt/brigada-core-src/gradlew -p "$BUILD_DIR" --no-daemon clean build
echo "BUILD_DIR=$BUILD_DIR"
sha256sum "$BUILD_DIR/build/libs/brigada-core-0.1.0.jar"
